import { finding } from '../../engine/checks/helpers/findings.mjs';

// Branches whose commits are authored by the scheduler, not by a session.
//
// WHY THEY ARE EXEMPT, and not "an issue reference someone forgot to add".
// The maintenance branch is written by baselining's PREPROCESSING — a code
// subprocess that converges the mount, commits, and pushes — and the dispatch
// issue that tracks the cycle is filed by `fileHandoff` only AFTER that
// preprocessing returns and asks for an agent (engine/scheduler/run.mjs). The
// issue number does not exist at commit time, so no amount of care in the worker
// can put it in the commit message: the ordering forbids it, not an oversight.
//
// What the executor session inherits is therefore a branch of already-pushed
// machine commits with no `#N` in them, and this rule fired on every nightly
// run. The two ways out both cost more than they buy — force-push a rewritten
// message onto a shared PR branch (which packs/git-github/ explicitly forbids),
// or add an empty commit whose only content is the reference. So the branch
// family is named here instead, once, where the exemption is visible.
const MACHINE_BRANCHES = [
  /^claudinite\/maintenance(?:-|$)/,   // baselining's per-cycle maintenance PR
];

const rule = {
  id: 'task-lifecycle',
  severity: 'blocking',
  description: 'Work on a branch must reference a GitHub issue in at least one commit message',
  doc: 'packs/basics/RULES.md',
  scope: 'work',
  why: 'every task starts from an issue; the reference is what ties the branch to it',

  run(work) {
    const { commits } = work;
    if (work.onDefaultBranch() || !commits.length || commits.some((m) => /#\d+/.test(m))) return [];
    if (MACHINE_BRANCHES.some((re) => re.test(work.branch ?? ''))) return [];
    return [finding(rule, {
      file: '(branch)',
      what: `none of the ${commits.length} commit(s) since ${work.baseRef} references an issue (#N)`,
      // Amending is only offered for a commit that is still local. Once it is
      // pushed — the usual case on a branch with an open PR — rewriting it means
      // a force-push over shared history, which packs/git-github/ forbids; a new
      // commit carrying the reference is the cheap, correct move there.
      fix: 'create or locate the GitHub issue for this task and reference it (e.g. "Refs #N", "Closes #N") in a commit message — '
        + 'amend the latest commit if it is still unpushed, otherwise add a new commit rather than rewriting pushed history',
    })];
  },
};

export default rule;

