// and the dispatch issue that tracks the cycle is filed only after preprocessing
// returns — so the number cannot exist at commit time. Flagging it asked the
// executor to force-push over a shared PR branch to satisfy a check.
test('task-lifecycle: exempts the scheduler-authored maintenance branch', () => {
  const root = makeRepo({ changed: { 'f.txt': 'x\n' }, commitMsg: 'Claudinite maintenance' });
  try {
    git(root, 'branch', '-m', 'claudinite/maintenance-2026-08-01-z0nih5');
    assert.equal(run(taskLifecycle, root).length, 0);
  } finally { cleanup(root); }
});

// The exemption is the machine branch family, not "anything under claudinite/".
test('task-lifecycle: still flags an ordinary branch that merely starts with claudinite/', () => {
  const root = makeRepo({ changed: { 'f.txt': 'x\n' }, commitMsg: 'no reference here' });
  try {
