// A routine trigger is not an owner comment. An unattended run arrives as a
// plain-string user turn with the harness's `[SCHEDULED TASK …]` wrapper already
// stripped, so none of the shape filters above see it — every nightly executor
// session was failing this rule for not "replying" to a prompt no human wrote.
// `origin.kind` is the discriminator, verified against a real transcript.
test('comment-classification: a scheduled-routine trigger is not an owner comment', () => {
  const root = makeRepo({ changed: { 'a.md': 'x\n' } });
  const routine = (text) => ({
    type: 'user',
    timestamp: '2026-08-01T03:58:00Z',
    origin: { kind: 'task-notification', subkind: 'scheduled-trigger' },
    message: { role: 'user', content: text },
  });
  try {
    // The exact shape that fired: a launcher prompt, then an unclassified reply.
    assert.equal(runWithTranscript(commentClassification, root, [
      routine('Execute the Claudinite executor: .claudinite/shared/engine/scheduler/executor.md'),
      reply('Running the dispatch now.'),
    ]).length, 0);

    // A subagent-completion notification is equally not an owner comment.
